def expand(graph, root):
    ordered, visited, active = [], set(), set()
    def visit(node):
        if node in active: raise ValueError('cycle')
        if node in visited: return
        active.add(node)
        for dependency in graph[node]: visit(dependency)
        active.remove(node)
        visited.add(node)
        ordered.append(node)
    visit(root)
    return ordered
